[CmdletBinding()] param([string]$ResourceName,[string]$ResourceType,[Parameter(Mandatory)][string]$ResourceGroup,[Parameter(Mandatory)][string]$OutputDirectory,[string]$Subscription)
. (Join-Path $PSScriptRoot 'Common-AzureCollector.ps1');$doc=New-CollectorDocument $ResourceType $ResourceName $ResourceGroup $Subscription
$resource=Invoke-AzCommandJson 'resource.show' @('resource','show','--resource-group',$ResourceGroup,'--name',$ResourceName,'--resource-type',$ResourceType) $Subscription -Required;Add-CollectorSection $doc 'show' $resource;if($resource.data.id){Add-StandardResourceEvidence $doc $resource.data.id $Subscription};$file=Join-Path $OutputDirectory ('communication-services-{0}.json' -f (ConvertTo-CollectorSafeFileName $ResourceName));Save-CollectorDocument $doc $file;[pscustomobject]@{resourceType='communicationServices';name=$ResourceName;outputFile=$file}